from __future__ import annotations

import os
from pathlib import Path

from dotenv import load_dotenv


ROOT = Path(__file__).resolve().parents[3]
BACKEND_DIR = ROOT / "backend"
# Env thật của host (Docker/Render/Railway…) luôn thắng. Local: backend/.env là file riêng của backend;
# .env.local ở root chỉ còn là fallback cho máy đang dùng một file chung (biến đã có thì không ghi đè).
load_dotenv(BACKEND_DIR / ".env", override=False)
load_dotenv(ROOT / ".env.local", override=False)

# Generated by `npm run data` from data/QuantumRegTech_Input_Data_final.xlsx; shared contract with the Next.js app.
DATA_DIR = Path(os.getenv("GENERATED_DATA_DIR") or ROOT / "data" / "generated")
COMPANIES_PATH = DATA_DIR / "companies.json"
PENDING_DATA_PATH = DATA_DIR / "universe_pending.json"
# Container không có volume → file SQLite mất khi redeploy; mount volume rồi trỏ biến này vào đó nếu cần giữ.
UNIVERSE_DB_PATH = Path(os.getenv("UNIVERSE_DB_PATH") or BACKEND_DIR / "universe.sqlite3")
DATA_VERSION = os.getenv("DATA_VERSION", "demo-v1")
METHODOLOGY_VERSION = os.getenv("METHODOLOGY_VERSION", "workbook-methodology-unconfirmed")
CORS_ORIGINS = [origin.strip() for origin in os.getenv("CORS_ORIGINS", "http://localhost:3000,http://127.0.0.1:3000").split(",") if origin.strip()]
